body.script:
        (function(){
          function dec(b){var s=atob(b);var a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return new TextDecoder().decode(a);}
          var frame=document.getElementById("arctic-embed-frame");
          var html=dec("");
          var base=new URL("./",location.href).href.replace(/\/+$/,"");
          var origins=["https://cdn.jsdelivr.net/gh/sealiee11/arctic-static@main","https://testingcf.jsdelivr.net/gh/sealiee11/arctic-static@main","https://gcore.jsdelivr.net/gh/sealiee11/arctic-static@main","https://cdn.statically.io/gh/sealiee11/arctic-static@main","https://esm.sh/gh/sealiee11/arctic-static@main"];
          var p=new URLSearchParams(location.search);
          var h=location.hash.slice(1);
          var directNetworkUrlAllowed=(function directNetworkUrlAllowed(value        , hasBackend         )          {
  const directProtocols = new Set(['http:', 'https:', 'ws:', 'wss:'])
  const apiHost = String.fromCharCode(97, 114, 99, 116, 105, 99, 46, 108, 97, 116)
  const ownerWispPaths = new Set(['/_q/', '/wisp/'])
  try {
    const url = new URL(value)
    if (!directProtocols.has(url.protocol)) return false
    if (hasBackend) return true
    const hostname = url.hostname.toLowerCase().replace(/\.+$/, '')
    if (hostname === apiHost) {
      return url.protocol === 'wss:' && url.search === '' && url.hash === '' && ownerWispPaths.has(url.pathname)
    }
    return !hostname.endsWith(`.${apiHost}`)
  } catch {
    return false
  }
});
          function targetOf(v){if(v.slice(0,4)==="aw1."){try{var q=v.slice(4).replace(/-/g,"+").replace(/_/g,"/"),s=atob(q+"=".repeat((4-q.length%4)%4)),a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return new TextDecoder().decode(a)}catch(e){return ""}}if(v.slice(0,4)!=="rv3."){try{return decodeURIComponent(v)}catch(e){return v}}try{var q=v.slice(4),k=[215,109,196,84,233,61,142,52,178,73,201,25],a=new Uint8Array(q.length/2);if(!/^(?:[0-9a-f]{2})+$/i.test(q))return "";for(var i=0;i<a.length;i++)a[i]=parseInt(q.slice(i*2,i*2+2),16)^(k[i%k.length]^((41+(i%k.length)*17)&255))^((41+i*29)&255);return new TextDecoder("utf-8",{fatal:true}).decode(a)}catch(e){return ""}}
          var target=h?targetOf(h):(p.get("url")||"");
          var route=p.get("r")||"",pinned=route?targetOf(route):(p.get("wisp")||"");if(!directNetworkUrlAllowed(pinned,false))pinned="";
          var attempt=-1,idle=0,maximum=0,settled=false,lastChance=false,progressCount=0,generation=0,frameGeneration=0,retrying=false,probe=null;
          function clearTimers(){clearTimeout(idle);clearTimeout(maximum);idle=0;maximum=0}
          function clearProbe(){if(probe){probe.abort();probe=null}}
          function send(data){if(window.parent!==window)window.parent.postMessage(data,"*")}
          function arm(g){if(settled||g!==generation)return;clearTimeout(idle);idle=setTimeout(function(){fail(g)},45000)}
          function start(index){if(settled||retrying)return;retrying=true;clearTimers();clearProbe();generation++;tryOrigin(index,generation)}
          function fail(g){if(settled||g!==generation)return;start(attempt+1)}
          function resetFrame(){var next=frame.cloneNode(false);frame.replaceWith(next);frame=next}
          window.addEventListener("message",function(e){if(!frame||e.source!==frame.contentWindow||frameGeneration!==generation)return;var d=e.data||{};if(d.type!=="arctic-embed")return;if(d.status==="ready"){settled=true;retrying=false;clearTimers();clearProbe();send(d)}else if(d.status==="progress"){if(typeof d.count==="number"&&d.count>progressCount){progressCount=d.count;arm(frameGeneration)}send(d)}else if(d.status==="navigate"){send(d)}else if(d.status==="wisp-failed"){settled=true;retrying=false;clearTimers();clearProbe();send(d)}else if(d.status==="error"){fail(frameGeneration)}});
          origins=origins.filter(function(origin){return origin.replace(/\/+$/,'')!==base});origins.unshift(base);
          function inject(origin,index,g){if(g!==generation||settled)return;attempt=index;settled=false;retrying=false;progressCount=0;clearTimers();clearProbe();resetFrame();frameGeneration=g;var head='<base href="'+origin+'/"/>'+'<'+'script>window.__ARCTIC_EMBED_TARGET='+JSON.stringify(target)+';window.__ARCTIC_EMBED_BACKEND='+JSON.stringify(p.get("backend")||"scramjet2")+';window.__ARCTIC_EMBED_PALETTE='+JSON.stringify(p.get("palette")||"")+';window.__ARCTIC_EMBED_WISP='+JSON.stringify(pinned)+';</'+'script>';frame.srcdoc=html.replace("<head>","<head>"+head);arm(g);maximum=setTimeout(function(){fail(g)},180000)}
          function exhausted(g){if(g!==generation||settled)return;if(!lastChance){lastChance=true;inject(base,origins.length,g);return}settled=true;retrying=false;clearTimers();clearProbe();send({type:"arctic-embed",status:"error",detail:"no runtime could start"})}
          function tryOrigin(index,g){if(g!==generation||settled)return;if(index>=origins.length){exhausted(g);return}var origin=origins[index].replace(/\/+$/,"");var c=new AbortController(),t=setTimeout(function(){c.abort()},5000);probe=c;fetch(origin+"/embed.html?z="+Date.now(),{cache:"no-store",mode:"cors",signal:c.signal}).then(function(r){if(!r.ok)throw new Error("runtime missing");return r.text()}).then(function(body){clearTimeout(t);if(g!==generation||settled||probe!==c)return;probe=null;if(body.indexOf('id="embed-root"')>=0)inject(origin,index,g);else tryOrigin(index+1,g)}).catch(function(){clearTimeout(t);if(g!==generation||settled||probe!==c)return;probe=null;tryOrigin(index+1,g)})}
          start(0);
        })();
